const listDownloads = `-- name: ListDownloads :many
SELECT download.id, download.acquisition_id, download.attempt, download.client_name, download.torrent_hash, download.status, download.progress, download.save_path, download.error_code, download.error_message, download.started_at, download.completed_at, download.created_at, download.updated_at, download.version, download.failure_stage, download.client_state, download.last_synced_at, download.deletion_requested_at, download.deleted_at, download.file_resolution_source, download.agent_resolution_id
FROM downloads AS download
WHERE download.deleted_at IS NULL
  AND ($1::text IS NULL OR download.status = $1::text)
  AND (
      $2::text IS NULL
      OR ($2::text = 'active' AND download.status IN ('enqueue_pending', 'file_resolution_pending', 'downloading'))
      OR (
          $2::text = 'waiting'
          AND (
              download.status IN ('enqueue_pending', 'file_resolution_pending')
              OR (download.status = 'downloading' AND download.client_state IN ('metaDL', 'queuedDL', 'stalledDL'))
          )
      )
      OR (
          $2::text = 'downloading'
          AND download.status = 'downloading'
          AND (
              download.client_state IS NULL
              OR download.client_state NOT IN ('metaDL', 'queuedDL', 'stalledDL', 'pausedDL', 'stoppedDL')
          )
      )
      OR (
          $2::text = 'paused'
          AND download.status = 'downloading'
          AND download.client_state IN ('pausedDL', 'stoppedDL')
      )
      OR (
          $2::text = 'completed'
          AND (
              download.status IN ('completed', 'selecting_files', 'materialized')
              OR (download.status = 'failed' AND download.failure_stage = 'materialize' AND download.progress = 1)
          )
      )
      OR (
          $2::text = 'failed'
          AND download.status = 'failed'
          AND download.failure_stage IS DISTINCT FROM 'materialize'
      )
  )
  AND (
      $3::text IS NULL
      OR download.id::text ILIKE '%' || $3::text || '%'
      OR COALESCE(download.save_path, '') ILIKE '%' || $3::text || '%'
      OR COALESCE(download.torrent_hash, '') ILIKE '%' || $3::text || '%'
      OR EXISTS (
          SELECT 1
          FROM acquisitions AS acquisition
          JOIN media_series AS media ON media.id = acquisition.series_id
          WHERE acquisition.id = download.acquisition_id
            AND (media.title ILIKE '%' || $3::text || '%' OR COALESCE(media.original_title, '') ILIKE '%' || $3::text || '%')
      )
  )
  AND (
      $4::uuid IS NULL
      OR (
          COALESCE($5::text, 'newest') = 'oldest'
          AND (download.created_at, download.id) > (
              SELECT cursor_download.created_at, cursor_download.id
              FROM downloads AS cursor_download
              WHERE cursor_download.id = $4::uuid
          )
      )
      OR (
          COALESCE($5::text, 'newest') = 'newest'
          AND (download.created_at, download.id) < (
              SELECT cursor_download.created_at, cursor_download.id
              FROM downloads AS cursor_download
              WHERE cursor_download.id = $4::uuid
          )
      )
  )
ORDER BY
    CASE WHEN COALESCE($5::text, 'newest') = 'oldest' THEN download.created_at END ASC,
    CASE WHEN COALESCE($5::text, 'newest') = 'newest' THEN download.created_at END DESC,
    CASE WHEN COALESCE($5::text, 'newest') = 'oldest' THEN download.id END ASC,
    CASE WHEN COALESCE($5::text, 'newest') = 'newest' THEN download.id END DESC
LIMIT $6
`

