const listRSSEntries = `-- name: ListRSSEntries :many
SELECT
    entry.id, entry.subscription_id, entry.release_candidate_id, entry.identity_key, entry.guid, entry.btih, entry.canonical_url, entry.title, entry.published_at, entry.status, entry.enqueue_attempts, entry.last_error_code, entry.last_error_message, entry.upstream_payload, entry.discovered_at, entry.enqueued_at, entry.updated_at, entry.download_uri, entry.downloadable, entry.rejection_reasons, entry.source_season, entry.source_episode, entry.duplicate_count, entry.last_error_retryable, entry.imported_at, entry.coordinate_source, entry.agent_resolution_id, entry.fulfillment_source,
    adjudication.batch_id AS adjudication_batch_id,
    COALESCE(adjudication.state, 'not_required')::text AS adjudication_state,
    adjudication.source AS adjudication_source,
    adjudication.resolution_id AS adjudication_resolution_id,
    adjudication.related_entry_id,
    EXISTS (
        SELECT 1
        FROM events AS enqueue
        JOIN events AS created
          ON created.resource_type = 'episode_task'
         AND created.topic = 'task.created'
         AND created.data->>'downloadId' = enqueue.data->>'downloadId'
        JOIN events AS imported
          ON imported.resource_type = 'episode_task'
         AND imported.resource_id = created.resource_id
         AND imported.topic = 'task.imported'
        WHERE enqueue.resource_type = 'rss_entry'
          AND enqueue.topic = 'rss.entry.enqueueing'
          AND enqueue.resource_id = entry.id
          AND enqueue.data ? 'acquisitionId'
          AND enqueue.data ? 'downloadId'
    ) AS successful_import_present
FROM rss_entries AS entry
LEFT JOIN rss_entry_adjudications AS adjudication ON adjudication.entry_id = entry.id
WHERE entry.subscription_id = $1
  AND ($2::text IS NULL OR entry.status = $2::text)
  AND (
      $3::uuid IS NULL
      OR (
          COALESCE($4::text, 'newest') = 'oldest'
          AND (entry.discovered_at, entry.id) > (
              SELECT cursor_entry.discovered_at, cursor_entry.id
              FROM rss_entries AS cursor_entry
              WHERE cursor_entry.id = $3::uuid
          )
      )
      OR (
          COALESCE($4::text, 'newest') = 'newest'
          AND (entry.discovered_at, entry.id) < (
              SELECT cursor_entry.discovered_at, cursor_entry.id
              FROM rss_entries AS cursor_entry
              WHERE cursor_entry.id = $3::uuid
          )
      )
  )
ORDER BY
    CASE WHEN COALESCE($4::text, 'newest') = 'oldest' THEN entry.discovered_at END ASC,
    CASE WHEN COALESCE($4::text, 'newest') = 'newest' THEN entry.discovered_at END DESC,
    CASE WHEN COALESCE($4::text, 'newest') = 'oldest' THEN entry.id END ASC,
    CASE WHEN COALESCE($4::text, 'newest') = 'newest' THEN entry.id END DESC
LIMIT $5
`

